(function () {
    const ada_bang_usaha = getValue('ada_bang_usaha')?.[0]?.value;
    const ada_keluarga = getValue('ada_keluarga')?.[0]?.value;

    return (
        (ada_bang_usaha && ada_bang_usaha != '0' && ada_bang_usaha != '3' && ada_bang_usaha != '4')
        || (ada_keluarga && ada_keluarga != '0' && ada_keluarga != '3' && ada_keluarga != '6')
    );
})();

(function () {
    const pilihUmkm =
        getValue('pilih_umkm')?.[0]?.description?.toLowerCase() || '';

    const adaBangUsaha =
        getValue('ada_bang_usaha')?.[0]?.value;

    const ecKeluarga =
        !!getValue('ec_keluarga');

    const UB =
        pilihUmkm.includes('[ub]') || getValue('skala_usaha_all')?.toLowerCase().includes('ub');
        if (UB) return false

    const adaBang =
        adaBangUsaha === '1' ||
        adaBangUsaha === '2';

    return (adaBang) || ecKeluarga;
})();

(function(){
    let ada = getValue('keberadaan_dtsen@$ROW$')?.[0].value
    if (getValue('mode') == 'CAWI') return false;

    if (getValue('is_cawi_keluarga')) return false

    return getValue('label_usaha') && (ada == 1 || ada == 5)
})()

(function(){
