(function(){
    const ec_ada_usaha = getValue('ec_ada_usaha')
    const nama_usaha_prelist = getValue('nama_usaha_prelist')
    const mulai = getValue('mulai')
    const select_ub = getValue('pilih_umkm')?.[0]?.description?.includes("[UB]");
    const kode_bang = getValue('kode_bang')?.[0]?.value
    const is_ub = getValue('jenis_prelist') == 'UB' || getValue('skala_usaha_all')?.includes('UB') || select_ub;
    const is_kp = getValue('ada_bang_usaha')?.[0]?.value == '7'
    const ada_keluarga = getValue('ada_keluarga')?.[0]?.value
    const is_not_eligible = ada_keluarga == '4'

    if (is_ub || is_kp || is_not_eligible) return false;

    if ((kode_bang == '4' || kode_bang == '5' || kode_bang == '6' || kode_bang == '8' || kode_bang == '9')) return false

    if (getValue('is_from_cawi') || getValue('is_cawi_keluarga')) return true

    const res = 
        (ec_ada_usaha || (
            (nama_usaha_prelist?.length && kode_bang != '8' && !!kode_bang) 
            || getValue('is_from_cawi'))
        )
    && !!mulai;

    return res
})()

